    public abstract class BaseGraphRepository<TEntity>
    {
        protected readonly IGraphReferenceManager _graph;

        protected BaseGraphRepository(IGraphReferenceManager graph)
        {
            _graph = graph;
        }

        protected async Task<TEntity?> GetResourceAsync(ResourceIdentifier identifier, Func<ResourceData, TEntity> mapper, CancellationToken ct = default)
        {
            var data = await _graph.GetResourceAsync(identifier);
            return data == null ? default : mapper(data);
        }

        protected async Task<IReadOnlyList<TEntity>> GetResourcesAsync(Func<ResourceData, bool> filter, Func<ResourceData, TEntity> mapper, CancellationToken ct = default)
        {
            var resources = await _graph.GetAllResourcesAsync();
            var filteredResources = resources.Where(filter).ToList();
            var entities = new List<TEntity>();

            foreach (var resource in filteredResources)
            {
                entities.Add(mapper(resource));
            }

            return entities.AsReadOnly();
        }
    }

