    public abstract class BaseModuleUnitOfWork : IModuleUnitOfWork
    {
        protected readonly IGraphReferenceManager _graph;
        private int _transactionDepth;

        public IModuleRepository Modules { get; }
        public IVersionRepository Versions { get; }
        public IArtifactRepository Artifacts { get; }
        public IRelationshipRepository Relationships { get; }
        public IProcessRepository Processes { get; }

        protected BaseModuleUnitOfWork(
            IGraphReferenceManager graph,
            IModuleRepository modules,
            IVersionRepository versions,
            IArtifactRepository artifacts,
            IRelationshipRepository relationships,
            IProcessRepository processes)
        {
            _graph = graph ?? throw new ArgumentNullException(nameof(graph));
            Modules = modules;
            Versions = versions;
            Artifacts = artifacts;
            Relationships = relationships;
            Processes = processes;
        }

        public virtual async Task<int> SaveChangesAsync(CancellationToken ct = default)
        {
            await Task.CompletedTask;
            return 1;
        }

        public virtual async Task BeginTransactionAsync(CancellationToken ct = default)
        {
            _transactionDepth++;
            if (_transactionDepth == 1)
            {
                await Task.CompletedTask;
            }
        }

        public virtual async Task CommitTransactionAsync(CancellationToken ct = default)
        {
            if (_transactionDepth <= 0)
                throw new InvalidOperationException("No active transaction to commit.");

            _transactionDepth--;
            if (_transactionDepth == 0)
            {
                await SaveChangesAsync(ct);
            }
        }

        public virtual async Task RollbackTransactionAsync(CancellationToken ct = default)
        {
            if (_transactionDepth <= 0)
                throw new InvalidOperationException("No active transaction to rollback.");

            _transactionDepth = 0;
            await Task.CompletedTask;
        }

        public virtual void Dispose()
        {
            if (_transactionDepth > 0)
            {
                _transactionDepth = 0;
            }
        }
    }

    public class GraphModuleRepository : BaseGraphRepository<IModule>, IModuleRepository
    {
        public GraphModuleRepository(IGraphReferenceManager graph) : base(graph) { }

        public async Task<IModule?> GetByIdAsync(string id, CancellationToken ct = default)
        {
            var identifier = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = id };
            var dependencies = await GetModuleDependenciesAsync(id);
            return await GetResourceAsync(identifier, data => ResourceMapper.MapToModule(data, dependencies), ct);
        }

        public async Task<IModule?> GetByNameAsync(string name, string? version = null, CancellationToken ct = default)
        {
            if (string.IsNullOrEmpty(name)) return null;

            var allModules = await GetAllAsync(ct);
            return allModules.FirstOrDefault(m => m.Name == name && (version == null || m.Version == version));
        }

        public async Task<IReadOnlyList<IModule>> GetAllAsync(CancellationToken ct = default)
        {
            var modules = new List<IModule>();
            var allResources = await _graph.GetAllResourcesAsync();
            var moduleResources = allResources.Where(r => r.Identifier.ResourceType == GraphStorageConstants.ResourceTypes.Module).ToList();

            var dependenciesCache = new Dictionary<string, IReadOnlyList<string>>();
            foreach (var resource in moduleResources)
            {
                var moduleId = resource.Identifier.Id;
                if (!dependenciesCache.ContainsKey(moduleId))
                {
                    dependenciesCache[moduleId] = await GetModuleDependenciesAsync(moduleId);
                }
                modules.Add(ResourceMapper.MapToModule(resource, dependenciesCache[moduleId]));
            }

            return modules.AsReadOnly();
        }

        public async Task<IReadOnlyList<IModule>> FindByTagsAsync(IEnumerable<string> tags, CancellationToken ct = default)
        {
            var all = await GetAllAsync(ct);
            var tagSet = new HashSet<string>(tags);
            return all.Where(m => m.Tags.Any(tagSet.Contains)).ToList().AsReadOnly();
        }

        public async Task<bool> AddAsync(IModule module, CancellationToken ct = default)
        {
            var resource = ResourceIdentifierFactory.CreateModuleIdentifier(module);
            if (_graph.ContainsResource(resource)) return false;

            var metadata = new Dictionary<string, object>
            {
                [GraphStorageConstants.Keys.Version] = module.Version,
                [GraphStorageConstants.Keys.Author] = module.Author,
                [GraphStorageConstants.Keys.Description] = module.Description,
                [GraphStorageConstants.Keys.Tags] = module.Tags.ToList(),
                [GraphStorageConstants.Keys.Documentation] = module.Documentation
            };

            foreach (var kv in module.Properties) metadata[kv.Key] = kv.Value;
            await _graph.AddResourceAsync(resource, metadata, symbol: module.Id);

            foreach (var dependencyId in module.Dependencies)
            {
                var target = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = dependencyId };
                await _graph.AddReferenceAsync(resource, target, ReferenceType.DependsOn);


            }

            return true;
        }

        public async Task<bool> UpdateAsync(IModule module, CancellationToken ct = default)
        {
            var resource = ResourceIdentifierFactory.CreateModuleIdentifier(module);
            if (!_graph.ContainsResource(resource)) return false;

            var metadata = new Dictionary<string, object>
            {
                [GraphStorageConstants.Keys.Version] = module.Version,
                [GraphStorageConstants.Keys.Author] = module.Author,
                [GraphStorageConstants.Keys.Description] = module.Description,
                [GraphStorageConstants.Keys.Tags] = module.Tags.ToList(),
                [GraphStorageConstants.Keys.Documentation] = module.Documentation
            };

            foreach (var kv in module.Properties) metadata[kv.Key] = kv.Value;
            await _graph.UpdateResourceAsync(resource, metadata, symbol: module.Id);
            return true;
        }

        public async Task<bool> DeleteAsync(string id, CancellationToken ct = default)
        {
            var resource = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = id };
            if (!_graph.ContainsResource(resource)) return false;
            await _graph.RemoveResourceAsync(resource);
            return true;
        }

        private async Task<IReadOnlyList<string>> GetModuleDependenciesAsync(string moduleId)
        {
            var resource = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = moduleId };
            var refs = await _graph.GetReferencesAsync(resource, includeIncoming: false);
            return refs.Where(r => r.Type == ReferenceType.DependsOn).Select(r => r.Target.Id).ToList();
        }
    }

    public class GraphVersionRepository : BaseGraphRepository<IModuleVersion>, IVersionRepository
    {
        public GraphVersionRepository(IGraphReferenceManager graph) : base(graph) { }

        public async Task<IModuleVersion?> GetVersionAsync(string moduleId, string versionNumber, CancellationToken ct = default)
        {
            var identifier = new ResourceIdentifier
            {
                ResourceType = GraphStorageConstants.ResourceTypes.ModuleVersion,
                Id = RelationshipCodec.BuildVersionId(moduleId, versionNumber)
            };
            return await GetResourceAsync(identifier, ResourceMapper.MapToVersion, ct);
        }

        public async Task<IReadOnlyList<IModuleVersion>> GetVersionHistoryAsync(string moduleId, CancellationToken ct = default)
        {
            var moduleResource = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = moduleId };
            var refs = await _graph.GetReferencesAsync(moduleResource, includeIncoming: false);
            var versions = new List<IModuleVersion>();

            foreach (var r in refs.Where(r => r.Type == ReferenceType.Other && r.Description == RelationshipDescriptions.HasVersion))
            {
                if (await _graph.GetResourceAsync(r.Target) is { } data)
                {
                    versions.Add(ResourceMapper.MapToVersion(data));
                }
            }

            return versions.OrderByDescending(v => v.CommittedAt).ToList().AsReadOnly();
        }

        public async Task<bool> AddVersionAsync(IModuleVersion version, CancellationToken ct = default)
        {
            var resource = ResourceIdentifierFactory.CreateModuleVersionIdentifier(version);
            var metadata = new Dictionary<string, object>
            {
                [GraphStorageConstants.Keys.ModuleId] = version.ModuleId,
                [GraphStorageConstants.Keys.VersionNumber] = version.VersionNumber,
                [GraphStorageConstants.Keys.ChangeLog] = version.ChangeLog,
                [GraphStorageConstants.Keys.CommittedAt] = version.CommittedAt,
                [GraphStorageConstants.Keys.PreviousVersionId] = version.PreviousVersionId ?? ""
            };

            foreach (var kv in version.Properties) metadata[kv.Key] = kv.Value;
            await _graph.AddResourceAsync(resource, metadata, symbol: version.Id);
            await _graph.AddReferenceAsync(
                new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = version.ModuleId },
                resource,
                ReferenceType.Other,
                description: RelationshipDescriptions.HasVersion
            );

            return true;
        }

        public async Task<string?> GetLatestVersionNumberAsync(string moduleId, CancellationToken ct = default)
        {
            var versions = await GetVersionHistoryAsync(moduleId, ct);
            return versions.OrderByDescending(v => v.CommittedAt).FirstOrDefault()?.VersionNumber;
        }
    }

    public class GraphRelationshipRepository : BaseGraphRepository<IModuleRelationship>, IRelationshipRepository
    {
        private readonly ConcurrentDictionary<string, (string SourceId, string TargetId, ReferenceType Type)> _idMapping = new();

        public GraphRelationshipRepository(IGraphReferenceManager graph) : base(graph) { }

        public async Task<bool> AddAsync(IModuleRelationship relationship, CancellationToken ct = default)
        {
            var source = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = relationship.SourceId };
            var target = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = relationship.TargetId };
            var refType = RelationshipCodec.MapRelationshipType(relationship.Type);

            string relId = string.IsNullOrEmpty(relationship.Id)
                ? RelationshipCodec.BuildRelationshipId(relationship.SourceId, relationship.TargetId, refType)
                : relationship.Id;

            string description = RelationshipCodec.EncodeDescriptionWithId(relationship.Type.ToString(), relId);
            _idMapping.TryAdd(relId, (relationship.SourceId, relationship.TargetId, refType));

            await _graph.AddReferenceAsync(
                source,
                target,
                refType,
                description: description,
                strength: 1.0,
                location: relationship.VersionConstraint
            );

            return true;
        }

        public async Task<bool> RemoveAsync(string id, CancellationToken ct = default)
        {
            if (_idMapping.TryGetValue(id, out var info))
            {
                var source = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = info.SourceId };
                var target = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = info.TargetId };
                await _graph.RemoveReferenceAsync(source, target, info.Type);
                _idMapping.TryRemove(id, out _);
                return true;
            }

            var allResources = await _graph.GetAllResourcesAsync();
            foreach (var resource in allResources)
            {
                var refs = await _graph.GetReferencesAsync(resource.Identifier, includeIncoming: false);
                var match = refs.FirstOrDefault(r => RelationshipCodec.TryExtractRelId(r.Description, out var extracted) && extracted == id);
                if (match != default)
                {
                    await _graph.RemoveReferenceAsync(match.Source, match.Target, match.Type);
                    return true;
                }
            }

            return false;
        }

        public async Task<IReadOnlyList<IModuleRelationship>> GetOutgoingAsync(string sourceId, RefModels.ReferenceType? type = null, CancellationToken ct = default)
        {
            var source = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = sourceId };
            var refs = await _graph.GetReferencesAsync(source, includeIncoming: false);
            return MapReferencesToRelationships(refs, sourceId, null, type);
        }

        public async Task<IReadOnlyList<IModuleRelationship>> GetIncomingAsync(string targetId, RefModels.ReferenceType? type = null, CancellationToken ct = default)
        {
            var target = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Module, Id = targetId };
            var refs = await _graph.GetReferencesAsync(target, includeIncoming: true);
            return MapReferencesToRelationships(refs, null, targetId, type);
        }

        private IReadOnlyList<IModuleRelationship> MapReferencesToRelationships(
            IEnumerable<(ResourceIdentifier Source, ResourceIdentifier Target, ReferenceType Type, string? Location, string? Description, double Strength)> refs,
            string? sourceId,
            string? targetId,
            RefModels.ReferenceType? type)
        {
            var result = new List<IModuleRelationship>();

            foreach (var r in refs)
            {
                if (type != null && RelationshipCodec.MapReferenceTypeToRelationship(r.Type) != type) continue;

                string relId = RelationshipCodec.TryExtractRelId(r.Description, out var extracted) ? extracted : Guid.NewGuid().ToString("N");
                RefModels.ReferenceType relationshipType = RelationshipCodec.MapReferenceTypeToRelationship(r.Type);

                result.Add(new ModuleRelationshipRecord
                {
                    Id = relId,
                    SourceId = sourceId ?? r.Source.Id,
                    TargetId = targetId ?? r.Target.Id,
                    Type = relationshipType,
                    VersionConstraint = r.Location
                });
            }

            return result.AsReadOnly();
        }

    }

    public class GraphArtifactRepository : BaseGraphRepository<IModuleArtifact>, IArtifactRepository
    {
        public GraphArtifactRepository(IGraphReferenceManager graph) : base(graph) { }

        public async Task<IModuleArtifact?> GetByIdAsync(string id, CancellationToken ct = default)
        {
            var identifier = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Artifact, Id = id };
            return await GetResourceAsync(identifier, ResourceMapper.MapToArtifact, ct);
        }

        public async Task<IReadOnlyList<IModuleArtifact>> GetByModuleVersionAsync(string moduleId, string version, CancellationToken ct = default)
        {
            var versionId = RelationshipCodec.BuildVersionId(moduleId, version);
            var versionResource = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.ModuleVersion, Id = versionId };
            var versionData = await _graph.GetResourceAsync(versionResource);
            if (versionData == null) return Array.Empty<IModuleArtifact>();

            var artifacts = new List<IModuleArtifact>();
            if (versionData.Metadata.TryGetValue("Artifacts", out var artList) && artList is IEnumerable<object> artObjects)
            {
                foreach (var artObj in artObjects)
                {
                    if (artObj is ResourceData artData)
                    {
                        artifacts.Add(ResourceMapper.MapToArtifact(artData));
                    }
                }
            }

            var refs = await _graph.GetReferencesAsync(versionResource, includeIncoming: false);
            foreach (var r in refs.Where(r => r.Type == ReferenceType.Includes))
            {
                var artData = await _graph.GetResourceAsync(r.Target);
                if (artData != null)
                {
                    artifacts.Add(ResourceMapper.MapToArtifact(artData));
                }
            }

            return artifacts.AsReadOnly();
        }

        public async Task<bool> AddAsync(IModuleArtifact artifact, CancellationToken ct = default)
        {
            var resource = ResourceIdentifierFactory.CreateArtifactIdentifier(artifact);
            var metadata = new Dictionary<string, object>
            {
                [GraphStorageConstants.Keys.ModuleId] = artifact.ModuleId,
                [GraphStorageConstants.Keys.ContentType] = artifact.ContentType,
                [GraphStorageConstants.Keys.ContentHash] = artifact.ContentHash,
                [GraphStorageConstants.Keys.Content] = artifact.Content
            };

            foreach (var kv in artifact.Metadata) metadata[kv.Key] = kv.Value;
            await _graph.AddResourceAsync(resource, metadata, symbol: artifact.Id);
            return true;
        }
    }

    public class GraphProcessRepository : BaseGraphRepository<IProcessDefinition>, IProcessRepository
    {
        public GraphProcessRepository(IGraphReferenceManager graph) : base(graph) { }

        public async Task<IProcessDefinition?> GetByIdAsync(string id, CancellationToken ct = default)
        {
            var identifier = new ResourceIdentifier { ResourceType = GraphStorageConstants.ResourceTypes.Process, Id = id };
            return await GetResourceAsync(identifier, MapToProcess, ct);
        }

        private static IProcessDefinition MapToProcess(ResourceData data)
        {
            var meta = data.Metadata;
            return new ProcessDefinitionRecord
            {
                Id = data.Identifier.Id,
                Name = data.Identifier.Name,
                Description = GraphStorageHelpers.GetMetaValue(meta, GraphStorageConstants.Keys.Description, string.Empty),
                SchemaJson = GraphStorageHelpers.GetMetaValue(meta, "SchemaJson", string.Empty),
                Steps = meta.TryGetValue("Steps", out var s) && s is IEnumerable<object> steps
                    ? steps.Select(x => x?.ToString() ?? string.Empty).Where(x => !string.IsNullOrEmpty(x))
                        .Select(name => new ProcessStep(name, string.Empty, new Dictionary<string, object>())).ToList()
                    : new List<ProcessStep>()
            };
        }

        public async Task<bool> AddAsync(IProcessDefinition process, CancellationToken ct = default)
        {
            var resource = ResourceIdentifierFactory.CreateProcessIdentifier(process);
            var metadata = new Dictionary<string, object>
            {
                [GraphStorageConstants.Keys.Description] = process.Description,
                ["SchemaJson"] = process.SchemaJson
            };

            await _graph.AddResourceAsync(resource, metadata, symbol: process.Id);
            return true;
        }
    }
